-- Lote 10: solicitudes 90001..100000 y datos relacionados.
USE reservas_db;
BEGIN;
INSERT INTO solicitudes_reserva
(id,solicitante_id,docente_id,laboratorio_id,materia_id,periodo_lectivo_id,fecha_reserva,hora_inicio,hora_fin,numero_participantes,motivo,observacion,estado,clave_idempotencia,creada_en,actualizada_en,version)
SELECT ('00000000-0000-4000-8000-'||lpad(i::STRING,12,'0'))::UUID,('10000000-0000-4000-8000-'||lpad(((i-1)%5000+1)::STRING,12,'0'))::UUID,('11000000-0000-4000-8000-'||lpad(((i-1)%500+1)::STRING,12,'0'))::UUID,('12000000-0000-4000-8000-'||lpad(((i-1)%100+1)::STRING,12,'0'))::UUID,('13000000-0000-4000-8000-'||lpad(((i-1)%300+1)::STRING,12,'0'))::UUID,('14000000-0000-4000-8000-'||lpad(((i-1)%8+1)::STRING,12,'0'))::UUID,DATE '2026-07-01'+((i-1)%549)::INT,CASE (i-1)%4 WHEN 0 THEN TIME '08:00' WHEN 1 THEN TIME '10:00' WHEN 2 THEN TIME '14:00' ELSE TIME '16:00' END,CASE (i-1)%4 WHEN 0 THEN TIME '10:00' WHEN 1 THEN TIME '12:00' WHEN 2 THEN TIME '16:00' ELSE TIME '18:00' END,5+((i-1)%36)::INT,'Carga académica reproducible para rendimiento','Semilla SCLI número '||i::STRING,'APROBADA','seed-solicitud-'||lpad(i::STRING,12,'0'),TIMESTAMPTZ '2026-01-01 00:00:00+00'+((i-1)%259200)*INTERVAL '1 second',TIMESTAMPTZ '2026-01-01 00:00:00+00'+((i-1)%259200)*INTERVAL '1 second',0 FROM generate_series(90001,100000) serie(i) ON CONFLICT(id) DO NOTHING;
INSERT INTO reservas(id,solicitud_id,laboratorio_id,responsable_id,fecha_reserva,hora_inicio,hora_fin,estado,codigo_reserva,creada_en,actualizada_en,version)
SELECT ('20000000-0000-4000-8000-'||lpad(i::STRING,12,'0'))::UUID,('00000000-0000-4000-8000-'||lpad(i::STRING,12,'0'))::UUID,('12000000-0000-4000-8000-'||lpad(((i-1)%100+1)::STRING,12,'0'))::UUID,('15000000-0000-4000-8000-'||lpad(((i-1)%50+1)::STRING,12,'0'))::UUID,DATE '2026-07-01'+((i-1)%549)::INT,CASE (i-1)%4 WHEN 0 THEN TIME '08:00' WHEN 1 THEN TIME '10:00' WHEN 2 THEN TIME '14:00' ELSE TIME '16:00' END,CASE (i-1)%4 WHEN 0 THEN TIME '10:00' WHEN 1 THEN TIME '12:00' WHEN 2 THEN TIME '16:00' ELSE TIME '18:00' END,CASE (i-1)%10 WHEN 0 THEN 'FINALIZADA' WHEN 1 THEN 'EN_CURSO' ELSE 'PROGRAMADA' END,'RES-SEED-'||lpad(i::STRING,12,'0'),TIMESTAMPTZ '2026-01-01 00:05:00+00'+((i-1)%259200)*INTERVAL '1 second',TIMESTAMPTZ '2026-01-01 00:05:00+00'+((i-1)%259200)*INTERVAL '1 second',0 FROM generate_series(90001,100000) serie(i) ON CONFLICT(id) DO NOTHING;
INSERT INTO historial_solicitudes(id,solicitud_id,estado_anterior,estado_nuevo,usuario_accion_id,comentario,fecha_hora)
SELECT ('30000000-0000-4000-8000-'||lpad(i::STRING,12,'0'))::UUID,('00000000-0000-4000-8000-'||lpad(i::STRING,12,'0'))::UUID,NULL,'PENDIENTE',('10000000-0000-4000-8000-'||lpad(((i-1)%5000+1)::STRING,12,'0'))::UUID,'Solicitud creada por semilla reproducible',TIMESTAMPTZ '2026-01-01 00:00:00+00'+((i-1)%259200)*INTERVAL '1 second' FROM generate_series(90001,100000) serie(i) ON CONFLICT(id) DO NOTHING;
INSERT INTO historial_solicitudes(id,solicitud_id,estado_anterior,estado_nuevo,usuario_accion_id,comentario,fecha_hora)
SELECT ('40000000-0000-4000-8000-'||lpad(i::STRING,12,'0'))::UUID,('00000000-0000-4000-8000-'||lpad(i::STRING,12,'0'))::UUID,'PENDIENTE','APROBADA',('15000000-0000-4000-8000-'||lpad(((i-1)%50+1)::STRING,12,'0'))::UUID,'Solicitud aprobada por semilla reproducible',TIMESTAMPTZ '2026-01-01 00:05:00+00'+((i-1)%259200)*INTERVAL '1 second' FROM generate_series(90001,100000) serie(i) ON CONFLICT(id) DO NOTHING;
INSERT INTO bloqueos_agenda(id,laboratorio_id,fecha,hora_inicio,hora_fin,motivo,creado_por,activo,creado_en,version)
SELECT ('50000000-0000-4000-8000-'||lpad(i::STRING,12,'0'))::UUID,('12000000-0000-4000-8000-'||lpad(((i-1)%100+1)::STRING,12,'0'))::UUID,DATE '2026-07-01'+((i-1)%549)::INT,CASE (i-1)%2 WHEN 0 THEN TIME '12:00' ELSE TIME '18:00' END,CASE (i-1)%2 WHEN 0 THEN TIME '13:00' ELSE TIME '19:00' END,'Mantenimiento programado de semilla',('15000000-0000-4000-8000-'||lpad(((i-1)%50+1)::STRING,12,'0'))::UUID,((i-1)%5)<>0,TIMESTAMPTZ '2026-01-01 00:00:00+00'+((i-1)%259200)*INTERVAL '1 second',0 FROM generate_series(9001,10000) serie(i) ON CONFLICT(id) DO NOTHING;
COMMIT;
